CREATE DATABASE IF NOT EXISTS student_management_system;
USE student_management_system;
CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS departments(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) UNIQUE NOT NULL,head VARCHAR(120),description TEXT);
CREATE TABLE IF NOT EXISTS students(id INT AUTO_INCREMENT PRIMARY KEY,student_id VARCHAR(30) UNIQUE NOT NULL,name VARCHAR(120) NOT NULL,father_name VARCHAR(120),email VARCHAR(150) UNIQUE NOT NULL,phone VARCHAR(30),gender ENUM('Male','Female','Other'),date_of_birth DATE,department_id INT,semester INT,address VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS subjects(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,credit_hours INT DEFAULT 3);
CREATE TABLE IF NOT EXISTS marks(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,subject_id INT NOT NULL,assignment DECIMAL(5,2) DEFAULT 0,midterm DECIMAL(5,2) DEFAULT 0,final_exam DECIMAL(5,2) DEFAULT 0,total DECIMAL(5,2) DEFAULT 0,percentage DECIMAL(5,2) DEFAULT 0,grade VARCHAR(3),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY one_mark(student_id,subject_id),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
